BEGIN TRANSACTION;
CREATE TABLE global_stats (key TEXT PRIMARY KEY, value INTEGER);
CREATE TABLE history (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            winner_id INTEGER,
            loser_id INTEGER
        );
CREATE TABLE songs (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                artist TEXT NOT NULL,
                cover_url TEXT,
                audio_url TEXT,
                elo_score REAL DEFAULT 1200,
                matches_played INTEGER DEFAULT 0
            , album TEXT, highest_elo REAL DEFAULT 1200, highest_rank INTEGER DEFAULT 9999, trivia_attempts INTEGER DEFAULT 0, trivia_correct INTEGER DEFAULT 0);
DELETE FROM "sqlite_sequence";
COMMIT;
